    ctx.fillStyle = phase ? '#ff4040' : '#4060ff';
    ctx.fillRect(-6, -W * 0.3, 12, 6);
    ctx.fillStyle = phase ? '#4060ff' : '#ff4040';
    ctx.fillRect(-6, W * 0.3 - 6, 12, 6);
  }
