    // building and not a slab of the ground it stands on.
    ctx.fillStyle = b.paint;
    ctx.fillRect(b.x, b.y, b.w, b.h);
    ctx.fillStyle = b.roof;
    ctx.fillRect(b.x + 9, b.y + 9, b.w - 18, b.h - 18);
    ctx.strokeStyle = 'rgba(43, 32, 22, 0.55)';
    ctx.lineWidth = 2.5;
